\begin{equation}
    \nabla_{\bm{z}} \widetilde{\Phi}\left(\bm{z}^{(j+1)};\bm{z}^{(j+1)}\right) = \overline{\bm{Q}}\left(\bm{Q} \bm{z}_k^{(j+1)} -\mathcal{R}_k\left(\bm{z}_k^{(j+1)}\right)\right) = 0\,.
\end{equation}

Therefore, we can conclude that
\begin{equation}
    \nabla_{\bm{z}}\Phi\left(\bm{z}^{(j+1)}\right) = \nabla_{\bm{z}} \widetilde{\Phi}\left(\bm{z}^{(j+1)};\bm{z}^{(j+1)}\right) = 0\,.
\end{equation}

